// Standalone fallback: resolve client_config from the Notion registry by client_id.
const trigger = $('Execute Workflow Trigger').first().json;
const wantId = trigger.client_id;
const rows = $input.all();
function prop(props, name){ const keys=[name,'property_'+name,'property_'+String(name).toLowerCase().replace(/ /g,'_')]; let p; for(const k of keys){ const v=props&&props[k]; if(v!==undefined&&v!==null){ p=v; break; } } if(p===undefined||p===null) return null; if(typeof p==='string') return p; return p.value ?? p.name ?? p.email ?? p.checkbox ?? p.text ?? p ?? null; }
let match=null;
for(const r of rows){ const props=r.json.properties||r.json; if(prop(props,'client_id')===wantId){ match=props; break; } }
if(!match) throw new Error(`No client registry row found for client_id='${wantId}'`);

// Outbound identity — keep in sync with 00-orchestrator-end-to-end.json -> 'Map Client Config'.
// Both addresses must be VERIFIED 'Send mail as' aliases on the Gmail account that owns the
// credential, or Gmail rejects drafts.send.
const DEMO_FROM_ALIAS = 'demo@cifral.io';
const PROD_FROM_ALIAS = 'proposal@cifral.io';
const clientStatus = prop(match,'Client Status');

const client_config = {
  client_id: wantId,
  client_name: prop(match,'Client Name'),
  status: clientStatus,
  from_alias: clientStatus === 'trial' ? DEMO_FROM_ALIAS : PROD_FROM_ALIAS,
  send_mode: String(prop(match,'send_mode') || 'send').trim().toLowerCase() === 'draft' ? 'draft' : 'send',
  service_tier: prop(match,'service_tier'),
  commercial_contact_email: prop(match,'commercial_contact_email'),
  templates: { en: prop(match,'template_id_en'), es: prop(match,'template_id_es') },
  proposals_folder_id: prop(match,'proposals_folder_id'),
  notification_chat_id: prop(match,'notification_chat_id')
};
return [{ json: { client_id: wantId, client_config, email_context: trigger.email_context || null, data: trigger.data, status: 'ok', errors: [] } }];

// Deterministic, scope-aware proposal assembly.
// Legacy fixes kept: B2 deterministic number; G2 template by language w/ EN fallback; G1 recipient
// = the client's own commercial contact; B1 requirements read the 'quantity' key.
//
// Phase 10 (delivery): resolves the send-as alias, the send mode and the RFQ thread to reply into.
// Phase 11 (document): emits a STRUCTURED render context for docxtemplater instead of
// pre-formatted text. Real headings, native bullets and a price table are structure, and structure
// cannot travel through a text placeholder — which is why the Google Docs find-and-replace
// pipeline was replaced. Template authoring: docs/TEMPLATE-GUIDE.md.
//
// SOURCE OF TRUTH mirrored in modules/proposal/render_context.js — change both, and check with
// `node modules/proposal/render_context.js`.
// === PROPOSAL RENDER CORE START ===

// Scope-of-supply labels — source of truth: schemas/scope-catalog.json.
const SCOPE_LABELS = {
  materials: { en: 'Materials & Equipment Supply', es: 'Suministro de materiales y equipos' },
  engineering: { en: 'Engineering & Design', es: 'Ingeniería y diseño' },
  installation: { en: 'Installation / Assembly', es: 'Instalación / Montaje' },
  commissioning: { en: 'Commissioning & Start-up', es: 'Puesta en marcha' },
  project_management: { en: 'Project Management', es: 'Gestión de proyecto' },
  spare_parts: { en: 'Spare Parts', es: 'Repuestos' },
  shipping: { en: 'Shipping & Logistics', es: 'Transporte y logística' },
  training: { en: 'Training', es: 'Formación' },
  warranty: { en: 'Warranty', es: 'Garantía' },
};
const SCOPE_ORDER = Object.keys(SCOPE_LABELS);

// Pricing line labels. These are COST categories (Module 3 / the client's rate card), which are
// not quite scope keys — the rate card calls on-site labour 'assembly' where the scope calls it
// 'installation'.
const COST_CATEGORY_LABELS = {
  materials: { en: 'Materials & Equipment', es: 'Materiales y equipos' },
  engineering: { en: 'Engineering & Design', es: 'Ingeniería y diseño' },
  assembly: { en: 'Installation / Assembly', es: 'Instalación / Montaje' },
  commissioning: { en: 'Commissioning & Start-up', es: 'Puesta en marcha' },
  project_management: { en: 'Project Management', es: 'Gestión de proyecto' },
  training: { en: 'Training', es: 'Formación' },
};

// Narrative sections produced by Module 2, in document order.
const NARRATIVE_SECTIONS = [
  'alcance_tecnico',
  'resumen_comercial',
  'plan_implantacion',
  'repuestos',
  'transporte',
  'formacion',
  'garantia',
];

const BULLET_RE = /^[•‣◦⁃∙*\-–—]\s+/;

function pickLanguage(value) {
  return value === 'es' ? 'es' : 'en';
}

function labelFor(map, key, lang) {
  const entry = map[key];
  return (entry && entry[lang]) || key;
}

/**
 * Turn one of Module 2's plain-text sections into paragraphs and bullet lines.
 *
 * Module 2's system prompt pins the format: no markdown, paragraphs separated by a blank line,
 * list items as '•  item'. We parse that rather than asking the LLM for structured JSON —
 * it keeps the contract between modules unchanged, costs nothing, and can't drift at runtime.
 * The markdown stripping and the extra bullet characters are tolerance for LLM drift, not part
 * of the contract.
 *
 * Paragraphs and bullets are returned as two separate lists. Every section in the prompt is
 * either all paragraphs, all bullets, or an intro paragraph followed by bullets, so ordering
 * survives. If a model ever interleaves them, nothing is lost — the bullets simply group after
 * the paragraphs.
 */
function parseNarrative(raw) {
  const text = (raw == null ? '' : String(raw)).replace(/\r\n/g, '\n').trim();
  const parrafos = [];
  const bullets = [];

  for (const block of text.split(/\n\s*\n/)) {
    let buffer = [];
    const flush = () => {
      if (buffer.length) parrafos.push({ texto: buffer.join(' ') });
      buffer = [];
    };
    for (const rawLine of block.split('\n')) {
      const line = cleanInline(rawLine);
      if (!line) continue;
      if (BULLET_RE.test(line)) {
        flush();
        const item = line.replace(BULLET_RE, '').trim();
        if (item) bullets.push({ texto: item });
      } else {
        buffer.push(line);
      }
    }
    flush();
  }

  return {
    parrafos,
    bullets,
    has_parrafos: parrafos.length > 0,
    has_bullets: bullets.length > 0,
  };
}

// Module 2 is told to emit plain text. Strip markdown emphasis / heading marks anyway so a drifting
// model can never put a literal '**' or '#' in front of a customer.
function cleanInline(line) {
  return String(line)
    .replace(/\*\*(.+?)\*\*/g, '$1')
    .replace(/__(.+?)__/g, '$1')
    .replace(/`([^`]+)`/g, '$1')
    .replace(/^#{1,6}\s+/, '')
    .trim();
}

function formatMoney(value, currency, lang) {
  const n = Number(value);
  if (value == null || !Number.isFinite(n)) return '';
  const locale = lang === 'es' ? 'es-ES' : 'en-US';
  if (currency) {
    try {
      return new Intl.NumberFormat(locale, { style: 'currency', currency }).format(n);
    } catch (e) {
      // Unknown/invalid ISO code — fall through to a plain number plus the raw code.
    }
  }
  const plain = new Intl.NumberFormat(locale, { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
  return currency ? `${plain} ${currency}` : plain;
}

function formatNumber(value, lang) {
  const n = Number(value);
  if (value == null || !Number.isFinite(n)) return '';
  return new Intl.NumberFormat(lang === 'es' ? 'es-ES' : 'en-US', { maximumFractionDigits: 2 }).format(n);
}

function textOf(value) {
  return value == null ? '' : String(value).trim();
}

/**
 * Build the docxtemplater render context for one proposal.
 *
 * Every key is always present (see the nullGetter note at the top of this file), so a template
 * that references a section which is out of scope renders nothing rather than "undefined".
 */
function buildRenderContext({ rfq, content, pricing, proposalNumber, fecha }) {
  rfq = rfq || {};
  content = content || {};

  const lang = pickLanguage(rfq.language);
  const client = rfq.client || {};
  const project = rfq.project || {};
  const scope = rfq.scope_of_supply || {};
  const reqs = Array.isArray(rfq.technical_requirements) ? rfq.technical_requirements : [];

  // B1: the extractor's key is 'quantity'; the legacy demo read 'qty' and silently dropped it.
  const requisitos = reqs.map((r) => ({
    item: textOf(r && r.item),
    cantidad: r && r.quantity != null ? formatNumber(r.quantity, lang) : '',
    spec: textOf(r && r.spec),
  }));

  const incluido = SCOPE_ORDER.filter((k) => scope[k] === true).map((k) => ({ etiqueta: labelFor(SCOPE_LABELS, k, lang) }));
  const excluido = SCOPE_ORDER.filter((k) => scope[k] === false).map((k) => ({ etiqueta: labelFor(SCOPE_LABELS, k, lang) }));

  const context = {
    numero_propuesta: textOf(proposalNumber),
    fecha: textOf(fecha),
    idioma: lang,

    cliente: {
      empresa: textOf(client.company),
      contacto: [client.contact_name, client.contact_last_name].filter(Boolean).join(' ').trim(),
      email: textOf(client.email),
      telefono: textOf(client.phone),
    },
    proyecto: {
      tipo: textOf(project.type),
      ubicacion: textOf(project.location),
      plazo: textOf(project.desired_deadline),
    },

    requisitos,
    has_requisitos: requisitos.length > 0,

    alcance_incluido: incluido,
    alcance_excluido: excluido,
    has_alcance_incluido: incluido.length > 0,
    has_alcance_excluido: excluido.length > 0,
  };

  // Narrative sections. An out-of-scope section arrives empty from Module 2, so has_<key> is
  // false and the template's whole block — heading included — is dropped.
  const sections_rendered = [];
  for (const key of NARRATIVE_SECTIONS) {
    const parsed = parseNarrative(content[key]);
    const present = parsed.has_parrafos || parsed.has_bullets;
    context[key] = parsed;
    context[`has_${key}`] = present;
    if (present) sections_rendered.push(key);
  }

  // Economic section. Lines are the CUSTOMER-FACING sell prices (Module 3's sell_amount), which
  // sum exactly to the total.
  //
  // The internal `subtotal` is deliberately NOT exposed here. It is the pre-margin cost basis, and
  // this document is forwarded by the reseller to their own end customer — printing the cost basis
  // beside the total hands the customer the reseller's margin. The reseller still sees the subtotal
  // in the quote email the orchestrator sends them.
  const cur = (pricing && pricing.currency) || '';
  const lineasSrc = pricing && Array.isArray(pricing.lines) ? pricing.lines : [];
  const lineas = lineasSrc.map((l) => ({
    concepto: labelFor(COST_CATEGORY_LABELS, l && l.category, lang),
    cantidad: l && l.hours != null ? formatNumber(l.hours, lang) : '',
    precio_unitario: l && l.rate != null ? formatMoney(l.rate, cur, lang) : '',
    importe: formatMoney(l && (l.sell_amount != null ? l.sell_amount : l.amount), cur, lang),
  }));

  context.has_pricing = !!pricing;
  context.pricing = {
    lineas,
    has_lineas: lineas.length > 0,
    total: pricing ? formatMoney(pricing.total, cur, lang) : '',
    condiciones_pago: pricing ? textOf(pricing.payment_terms) : '',
    moneda: cur,
  };
  if (pricing) sections_rendered.push('economic');

  return { context, sections_rendered, language: lang };
}
// === PROPOSAL RENDER CORE END ===

// --- n8n wrapper ---
const cfg = $json.client_config || {};
const data = $json.data || {};
const rfq = data.rfq || {};
const client = rfq.client || {};
const reqs = Array.isArray(rfq.technical_requirements) ? rfq.technical_requirements : [];
const lang = pickLanguage(rfq.language);

// B2: same RFQ in, same number out — no Date.now(), no random.
function hash36(str){ let h=5381; for(let i=0;i<str.length;i++){ h=((h<<5)+h+str.charCodeAt(i))>>>0; } return h.toString(36); }
const identity = [ $json.client_id, client.company, client.email, (reqs[0]&&reqs[0].item)||'' ].join('|');
const suffix = (hash36(identity) + '000000').slice(0,6).toUpperCase();
const proposal_number = `PROP-${$now.toFormat('yyyyMMdd')}-${suffix}`;
const fecha = $now.toFormat(lang === 'es' ? 'dd/MM/yyyy' : 'yyyy-MM-dd');

// G2: template by language, EN fallback. These now point at a .docx FILE in Drive, not a Google Doc.
const templates = cfg.templates || {};
const template_id = templates[lang] || templates.en;
if(!template_id) throw new Error(`No .docx template configured for client '${$json.client_id}' (language '${lang}', no EN fallback).`);

// G1: never the extracted end customer. This mail is DELIVERED, not parked as a draft.
const recipient_email = cfg.reply_to || cfg.commercial_contact_email;
if(!recipient_email) throw new Error(`No reply address for '${$json.client_id}' (sender email + commercial_contact_email both empty). Refusing to send to the extracted end customer (legacy gap G1).`);

// Outbound identity. The Gmail node's Send operation rebuilds From from the authenticated mailbox,
// so the alias only survives the create-draft -> drafts.send pair.
const from_alias = cfg.from_alias || '';
if(!from_alias) throw new Error(`No from_alias resolved for '${$json.client_id}'. Refusing to send from the raw mailbox address.`);
const send_mode = String(cfg.send_mode || 'send').trim().toLowerCase() === 'draft' ? 'draft' : 'send';

// Reply inside the reseller's original RFQ thread. Gmail threads on threadId AND a matching
// subject; '' rather than null so the Gmail node treats it as falsy and omits the field.
const ec = $json.email_context || {};
const thread_id = ec.thread_id || '';
const email_subject = ec.reply_subject || `Proposal ${proposal_number} — ${client.company || 'Client'}`;

const built = buildRenderContext({ rfq, content: data.content, pricing: data.pricing, proposalNumber: proposal_number, fecha });

const doc_name = `Proposal ${proposal_number} - ${client.company || 'Client'}`;

return [{ json: {
  client_id: $json.client_id,
  language: built.language,
  proposal_number,
  fecha,
  template_id,
  proposals_folder_id: cfg.proposals_folder_id,
  recipient_email,
  from_alias,
  send_mode,
  thread_id,
  email_subject,
  notification_chat_id: cfg.notification_chat_id,
  client_status: cfg.status || '',
  doc_name,
  docx_file_name: `${doc_name}.docx`,
  pdf_file_name: `${doc_name}.pdf`,
  sections_rendered: built.sections_rendered,
  render_context: built.context,
  company: client.company || '',
  project_type: (rfq.project && rfq.project.type) || ''
} }];

// The docxtemplater node returns a fresh item — `json: {}` and ONLY its own output binary — so
// nothing upstream survives it, and the Drive upload downstream replaces the item with file
// metadata. Rather than depend on each node's binary-passthrough behaviour, rebuild the item
// explicitly from the node that owns the bytes. Same reason 'Collect Artifacts' exists.
const rendered = $('Render Docx').first();
const fields = $('Compute Proposal Fields').first().json;
return [{ json: fields, binary: { docx: rendered.binary.docx } }];

// Reassemble both attachments onto one item: the editable .docx (what the reseller tweaks before
// forwarding) and the PDF (what they forward as-is). Pulled straight from the two nodes that
// produced them, so no intermediate node's binary handling can drop one.
const fields = $('Compute Proposal Fields').first().json;
const docx = $('Render Docx').first().binary.docx;
const pdf = $('Convert To PDF').first().binary.pdf;
const uploaded = $('Upload Docx To Drive').first().json;
return [{
  json: { ...fields, document_id: uploaded.id || null, document_url: uploaded.webViewLink || null },
  binary: { docx, pdf }
}];

